import sys
sys.path.insert(0, '/home/user/cautious-chainsaw/tmp/fence-3/scripts')
from rowlib import Row
from cite import OR, SV, LIB, WEB, NPSW

SS_BASE = 'https://gettysburg.stonesentinels.com/battlefield-farms/'


def S058():
    R = Row('S-058')
    we1 = R.cite(OR(1, 'this brigade was put in position at 6.30 a. m. on the 2d, on Granite Ridge', rec='OR27-1-R104', note='Sentence continues "on the right of the division, its right resting on Cushing\'s battery (A, Fourth U. S. Artillery)".'))
    we2 = R.cite(OR(1, 'was placed behind a fence a little in advance of the ridge', rec='OR27-1-R104', note='OCR reads "The Sixtyninth Regiment" before the quotation.'))
    gi = R.cite(OR(1, "Webb's brigade on the right, partially behind a low stone wall, and protecting Cushing's battery", rec='OR27-1-R098', note='Gibbon, the Second Corps division on the line at about 16:00 on 2 Jul (the advance of the Third Corps).'))
    ha1 = R.cite(OR(1, "The morning of July 3 was quiet until about 8 o'clock, when the enemy suddenly opened fire upon our position, exploding three limbers of Battery A, Fourth U. S. Artillery", rec='OR27-1-R132', page='478-479', note='Printed page 478 or 479 (the page model gives 478-479; the passage precedes the heading of p.479). Hazard, chief of artillery, Second Corps.'))
    ha2 = R.cite(OR(1, 'fell on July 3, mortally wounded by a musket-shot', rec='OR27-1-R132', note='Sentence: "First Lieut. A. H. Cushing, commanding Battery A, Fourth U. S. Artillery, fell on July 3, mortally wounded by a musket-shot."'))
    hu = R.cite(OR(1, "Cushing's (A, Fourth United States, six 3-inch)", rec='OR27-1-R028', nth=0, note='First of three occurrences (p.236): the battery of six 3-inch rifles in the Second Corps line.'))
    hl1 = R.cite(OR(1, 'Three of his limbers were blown up and changed with the caisson limbers under fire.', rec='OR27-1-R109', page='437-438', note='Printed page 437 or 438 (page model range). Hall, 2nd Brigade, 2nd Division, Second Corps.'))
    hl2 = R.cite(OR(1, 'he pushed his gun to the fence in front, and was killed while serving his last canister into the ranks of the advancing enemy', rec='OR27-1-R109', page='437-438', note='Printed page 437 or 438 (page model range).'))
    hl3 = R.cite(OR(1, 'slight cover of the rail fence', rec='OR27-1-R109', note='Sentence: "they crowded to the slight cover of the rail fence, mixing with the troops already there."'))
    ab = R.cite(OR(1, 'who was behind a rail fence', rec='OR27-1-R111', note='Sentence (Abbott, 20th Massachusetts): "When they arrived there, there was a very thin line contending with the enemy, who was behind a rail fence, with the exception of a small number that climbed over".'))
    we3 = R.cite(OR(1, "had silenced the Rhode Island battery and all the guns but one of Cushing's battery", rec='OR27-1-R104', note='Sentence begins "About 1 p. m. the enemy opened with more than twenty batteries upon our line. By 2.45 o\'clock".'))
    we4 = R.cite(OR(1, 'to the fence, carrying with them theii canister', rec='OR27-1-R104', note='OCR garbles the beginning of the sentence ("Three of Cushing\'s guns were ruh~3own"); the words "Three of Cushing\'s guns were" precede the quotation.'))
    we5 = R.cite(OR(1, 'The enemy advanced steadily to the fence, driving out a portion of the Seventy-first Pennsylvania Volunteers.', rec='OR27-1-R104'))
    we6 = R.cite(OR(1, 'General Armistead passed over the fence with probably over 100 of his command and with several battle-flags.', rec='OR27-1-R104'))
    we7 = R.cite(OR(1, "threw two companies of his command behind the stone wall on the right of Cushing's battery, 60 paces retired from the point of attack", rec='OR27-1-R104'))
    sm = R.cite(OR(1, 'protected by a stone wall from an infantry attack', rec='OR27-1-R106'))
    fi = R.cite(OR(1, 'near the stone fence in front of General Webb', rec='OR27-1-R330', note='Fitzhugh, 4th Volunteer Brigade, Artillery Reserve: batteries placed "near the stone fence in front of General Webb".'))
    ba = R.cite(LIB('BACH-STORY-1904', 'When Pickett advanced, he ran three of his pieces down to the wall where they are seen', title='J. B. Bachelder, The Story of the Battle of Gettysburg (1904 edition of the text to the Painting of the Repulse)', note='Participant-collected narrative; printed page not recoverable from the OCR text.'))
    R.sub('wall_pre_existing_on_2_jul', 'A stone wall and a fence stood on the Cemetery Ridge line where Webb\'s brigade and Cushing\'s battery formed on 2 Jul: Webb put the 69th Pennsylvania "behind a fence a little in advance of the ridge" at 06:30 on 2 Jul with his right on Cushing\'s battery, and Gibbon had the brigade "partially behind a low stone wall" at about 16:00.', 'documented', [we1, we2, gi],
          why='Existence of the wall and fence before the assault, on the day before it; no OR text describes their construction, so no construction animation is justified (CLAUDE.md, pre-existing features).')
    R.sub('three_limbers_exploded_about_08_00', 'Three limbers of Cushing\'s Battery A, 4th US Artillery, exploded when the Confederate guns opened suddenly at about 08:00 on the morning of 3 Jul, with little other loss.', 'documented', [ha1, hl1],
          why='Hazard dates it "about 8 o\'clock"; Hall confirms "three of his limbers were blown up". The printed "(morning)" is now an hour.')
    R.sub('guns_silenced_by_14_45', 'By 14:45 the Confederate cannonade had "silenced the Rhode Island battery and all the guns but one of Cushing\'s battery" (Webb); the battery had six 3-inch rifles.', 'documented', [we3, hu],
          why='The printed "four of six guns knocked out" has no source: Webb says all but one of the battery\'s guns were silenced, not four of six. "Silenced" is not "knocked out" (disabled); no OR text counts the disabled pieces.')
    R.sub('four_of_six_guns_knocked_out', 'Four of the six guns were knocked out (printed).', 'open_gap', [], support='none',
          why='Contradicted in wording by Webb ("all the guns but one" silenced by 14:45) and by Webb\'s "Three of Cushing\'s guns were run down to the fence" afterwards; no text gives four.')
    R.sub('guns_run_to_the_wall', 'When the assault came (from 15:00) three of Cushing\'s guns were run down to the fence/wall with their canister, and Cushing, severely wounded, "pushed his gun to the fence in front" and was killed there.', 'documented', [we4, hl2, ha2, ba],
          why='Webb p.428, Hall p.438, Hazard p.480, Bachelder. The OR calls the line "the fence" and "the wall" (Webb: "advanced to the wall on the right of the Sixty-ninth"; "the enemy advanced steadily to the fence"; Armistead "passed over the fence").')
    R.sub('wall_and_rail_fence_state_on_3_jul', 'The line the guns were run to had a stone wall with a rail fence in or at it: Hall "the slight cover of the rail fence", Abbott the enemy "behind a rail fence", Webb\'s "fence" and "stone wall", Smith "protected by a stone wall", Fitzhugh "the stone fence in front of General Webb".', 'documented', [hl3, ab, we5, we6, we7, sm, fi],
          why='Several witnesses use "fence" and "wall" for the same line; whether a rail fence ran on top of, in front of or beside the stone wall is not stated. The wall itself shows no damage in any text read.')
    R.sub('window_morning_to_15_30', 'The state changes run from about 08:00 on the morning of 3 Jul (limbers) to the assault at 15:00-15:30 (guns run to the wall, Cushing killed).', 'documented', [ha1, we3, we4],
          why='The printed upper bound "about 15:30" is the end of the assault at the Angle; the OR has no clock time for Cushing\'s death (Webb: "At 3 o\'clock the enemy\'s line of battle left the woods").')
    R.lookup('OR27 pt.1: Cushing, limbers, exploded, wall, fence in Hazard, Webb, Hall, Smith, Abbott, Fitzhugh, Gibbon', 'OR27', 'all quotes above', 'done')
    R.lookup('all local texts: Cushing with "four" or "three" guns', 'ws9, state volumes', 'Bachelder (three pieces run down to the wall); no text counts four disabled guns', 'done')
    R.unsupported('"Four of six guns knocked out" (no text).')
    R.unsupported('The sources Iron-9699 (a reprint of Hazard\'s report) and WHN-Cushing (Warfare History Network): Hazard\'s report is read directly in the OR; WHN is not admissible.')
    return R.finish('corrected', 'open',
        'Cushing\'s battery (six 3-inch rifles) stood at the Angle behind a pre-existing stone wall and a fence: three limbers blew up at about 08:00 on 3 Jul (Hazard, Hall); by 14:45 all the guns but one had been silenced (Webb); when the assault came three guns were run down to the fence/wall and Cushing was killed there (Webb, Hall, Hazard, Bachelder). "Four of six guns knocked out" is not supported by any text.',
        register=['fence-3-EG-05'],
        product=['State schedule S-058 / G-12: limbers exploded about 08:00 (documented); guns silenced to one by 14:45 (documented) instead of "four of six knocked out"; three guns run to the wall at 15:00-15:30 (documented). P-01 / FEN-cemetery-ridge-walls: wall and fence present at frame one on 2 Jul (documented), no construction animation, no damage state; the rail fence at the line is a documented detail (Hall, Abbott) whose placement is open (fence-3-EG-05).'],
        changes=['"Three limbers exploded (morning)" now has an hour (about 08:00, Hazard).', 'The shard row noted only existence; the failed Webb quote at p.427 is re-matched ("behind a fence a little in advance of the ridge").', '"Four of six guns knocked out" is flagged unsupported (Webb: all but one silenced).'])


def S059():
    R = Row('S-059')
    n1 = R.cite(NPSW('leister3d', 'Lydia Leister returned to her home after the battle to find 17 dead horses in her yard, all the hay was gone from her barn, and her fence rails had been burned.'))
    n2 = R.cite(NPSW('bldgs', 'The house and surrounding fences are all damaged and dead horses lay in various stages of rigormortis in the center of the Taneytown Road and in the yard of the house.',
                     note='NPS caption text for a Library of Congress photograph; the page does not date the photograph.'))
    n3 = R.cite(NPSW('leister_place', 'One shell burst in the yard among the staff horses tied to the fence, another tore up the steps of the house, another carried away the supports of the porch'))
    n4 = R.cite(NPSW('leister_place', 'As a result General Meade evacuated to a new headquarters.'))
    m1 = R.cite(LIB('MEADE-LL-v2', 'One shell burst in the yard among the staff horses tied to the fence, another tore up the steps of the house, another carried away the supports of the porch, one passed through the door, another through the garret', title='George Meade, The Life and Letters of George Gordon Meade, vol. 2 (1913), the account of Captain George Meade Jr., a member of the staff',
                    note='Printed page not recoverable from the OCR text (about p.106 by the running head "THE BATTLE OF GETTYSBURG 107" that follows). Participant account written decades later.'))
    h = R.cite(LIB('HASKELL-1908', "The house which was General Meade's headquarters was shot through several times, and a great many horses of officers and orderlies were lying dead around it.", title='Frank A. Haskell, The Battle of Gettysburg (letter written July 1863; printed 1908)'))
    ny = R.cite(SV('NY1', "The field around General Meade's headquarters, on the Taneytown Road, was strewn with the bodies of the dead horses", page='75'))
    sen = R.cite(LIB('ADAMS-SENTINEL-1863-08-18', 'singing of a bird which had a nest in a peach tree within thc yard', title='Adams Sentinel, 18 Aug 1863 (reprint of a New York Times correspondent\'s description, "The Storm of Shell")',
                     note='OCR reads "thc" for "the"; the passage describes 11:00-13:00 on 3 Jul at the "tiny farm house, 16 by 20" (OCR "16 by ilO").'))
    sen2 = R.cite(LIB('ADAMS-SENTINEL-1863-08-18', 'Eleven o\'clock', title='Adams Sentinel, 18 Aug 1863 (reprint of a New York Times correspondent\'s description, "The Storm of Shell")', note='The passage reads "Eleven o\'clock - twelve o\'clock - one o\'clock. In the shadow cast by the tiny farm house, 16 by 20, which Gen. Meade had made his headquarters, lay wearied staff officers and tired reporters"; after the singing of a bird in a peach tree in the yard "a shell screamed over the house, instantly followed by another" (the OCR of this part is garbled).'))
    sen3 = R.cite(LIB('ADAMS-SENTINEL-1863-08-18', 'They burst in the yard', title='Adams Sentinel, 18 Aug 1863 (reprint of a New York Times correspondent\'s description, "The Storm of Shell")', note='Continues (OCR "nest to the fence" for next to the fence): "burst next to the fence on both sides, garnished, as usual, with hitched horses".'))
    hb = R.cite(LIB('NPS-HB9-1954', "The Leister house and barn were badly damaged by the artillery fire which preceded Pickett's Charge.", title='NPS Historical Handbook 9, Gettysburg National Military Park (1954), stop 9'))
    hs = R.cite(LIB('NPS-HSR-LEISTER-BARN', 'Dead horses littered the yard, the crops were trampled', title='NPS Historic Structure Report: Leister Barn (physical fabric section)', note='The text layer interleaves words from two columns; only this contiguous run is quoted.'))
    t1 = R.cite(OR(1, 'when the enemy opened, at about 1 p. m., along his whole right, a furious cannonade on the left of our line', rec='OR27-1-R028'))
    t2 = R.cite(OR(1, 'I directed that the fire should be gradually stopped, which was done, and the enemy soon slackened his fire also', rec='OR27-1-R028'))
    R.sub('headquarters_and_use', 'The Leister house was Meade\'s headquarters from the early hours of 2 Jul; the Army council of war met there on the night of 2 Jul.', 'documented', [n4, hb],
          why='NPS web pages and Handbook 9. The row\'s from-state "Meade HQ" is supported.')
    R.sub('shells_struck_house_and_yard_during_cannonade', 'During the Confederate cannonade (from about 13:00 on 3 Jul) shells burst in the yard among the staff horses tied to the fence, tore up the steps, carried away the porch supports and passed through the door and the garret; the house was "shot through several times".', 'documented', [m1, h, n3, sen2, sen3, sen, t1],
          why='Captain George Meade Jr. (participant, 1913), Haskell (letter of July 1863), NPS (quoting Meade Jr.); the Sentinel\'s correspondent places the first shells over the "tiny farm house" at about 13:00. Printed "steps and porch supports down", "many shot holes": supported.')
    R.sub('dead_horses_17', '17 dead horses lay in the yard (and more in the Taneytown Road) when Lydia Leister returned.', 'documented', [n1, n2, ny, h],
          why='"17" rests on the NPS statement alone (the number is from her returned-home account / claim); contemporary and later witnesses (Haskell, NY at Gettysburg) confirm many dead horses around the house without a count.')
    R.sub('fence_rails_burned', 'Fence rails at the Leister farm had been burned by the time Lydia Leister returned after the battle; the surrounding fences were damaged.', 'documented', [n1, n2],
          why='NPS says "her fence rails had been burned" and, of the photograph, "the house and surrounding fences are all damaged". Neither says "all", who burned them or when; the printed window 13:00-15:00 on 3 Jul and the structures note "Jul 2-3" are not supported (the troops at the house burned wood on any of the three days and after).')
    R.sub('hay_lost', 'The hay was gone from the barn (printed "2 tons hay lost").', 'documented', [n1], support='partial',
          why='NPS: "all the hay was gone from her barn"; the amount (2 tons) is not in any local text.')
    R.sub('bedstead_apple_trees_peach_tree_spring', 'A shell broke a bedstead; apple trees destroyed; a peach tree died; the spring was spoiled.', 'open_gap', [], support='none',
          why='Searched bedstead, apple trees, peach tree, spring in all local texts: nothing for the Leister farm (the only peach tree is the living one with a bird\'s nest at about 13:00 in the Sentinel reprint). The PDF source is the damage claim via Stone Sentinels.')
    R.sub('window_13_00_to_15_00', 'The damage fell between about 13:00 and 15:00 on 3 Jul during the cannonade.', 'documented', [t1, t2, hb],
          why='Hunt: opened at about 1 p.m.; Union fire gradually stopped at about 2.30 p.m. and the enemy slackened soon after (end of the shelling 14:30-15:00; Hancock 1 h 45 min, Gibbon two hours, Lee about two hours; C-029 carried by the r03 shard). Applies to the shell damage and the dead horses, not to the rails.')
    R.lookup('all local texts: Leister with shot, steps, porch, bedstead, apple, peach, spring, hay, rails, fence', 'ws9, state volumes, OR27, NPS texts and pages', 'Meade LL v2, Haskell, NY1, Sentinel, NPS pages, HB9, HSR; no bedstead/apple/peach/spring text', 'done')
    R.lookup('NPS pages www.nps.gov (leister-house-3d, lydia-leister-farm, buildings-and-farms-then-and-now) re-read 2026-11-13', 'web (reachable host)', 'text saved under tmp/fence-3/web; the earlier shard\'s host home.nps.gov was refused, www.nps.gov answers', 'done')
    R.unsupported('Bedstead, apple trees destroyed, peach tree died, spring spoiled, 2 tons of hay (PDF sources SS-Leister and the claim file).')
    R.unsupported('"All rails burned" and the window 13:00-15:00 or Jul 2-3 for the burning.')
    return R.finish('corrected', 'blocked_host',
        'Leister house, 3 Jul: the cannonade from about 13:00 (to about 14:30-15:00) put shells through the yard (staff horses tied to the fence), the steps, the porch supports, the door and the garret; the house was shot through several times and many horses lay dead around it (Captain Meade, Haskell, NPS); when Lydia Leister returned she found 17 dead horses, the hay gone and her fence rails burned, and the surrounding fences damaged (NPS). "All" rails, the hour of the burning, the bedstead, apple and peach trees and the spoiled spring are not supported by any local text.',
        register=['fence-3-EG-06'],
        blocked_host=[{'url': SS_BASE, 'what_to_read': 'The Leister farm entry (key SS-Leister): the damage list (bedstead, apple trees, peach tree, hay in tons, spring, rails). Lead source; the primary is the damage claim.'},
                      {'url': 'Pennsylvania State Archives, Adams County damage claims (Leister, Lydia)', 'what_to_read': 'The itemised claim: hay, rails, trees, spring and the date of each loss. Not on the internet in a reachable form from here (owner-only act: a visit or a request). Series: Board of Commissioners to Assess Damages in Border Counties, War Damage Claims Abstracts, Record Group 2, Pennsylvania State Archives (the series the NPS McClean study cites as "Claim #3248 (Adams County)"); whether a file of this claimant is in that series was not checked.'}],
        product=['bld-leister-house: shell damage (steps, porch supports, door, garret) at 13:00-15:00 on 3 Jul is documented; bedstead and trees stay open-gap markers. FEN-leister: rails burned by the time she returned (documented), extent and time inferred; do not draw "all rails burned at 13:00-15:00 on 3 Jul"; show damaged fence sections with the 17 dead horses as the photograph shows them (NPS caption). Hay gone from the barn (documented).'],
        changes=['The NPS page is now read at www.nps.gov (the shard could use only a fetch summary of the home.nps.gov page).', 'Captain Meade, Haskell, NY at Gettysburg and the Sentinel document the shelling of the yard and the dead horses.', 'The 13:00-15:00 window is supported for the shell damage, not for the rails.'])


def S060():
    R = Row('S-060')
    no = R.cite(OR(1, "the general commanding, then at General Slocum's headquarters", rec='OR27-1-R017', note='Captain L. B. Norton, Chief Signal Officer, Army of the Potomac, on Captain D. E. Castle, who stayed at the signal station at Meade\'s headquarters on 3 Jul "when the enemy made their furious attack upon our center" after all others had been driven away.'))
    ba = R.cite(LIB('BACH-STORY-1904', "When the assault began he was at Major-General Slocum's headquarters, on Power's Hill, a half mile to the rear, near Culp's Hill, but reached this position on the field as it was repulsed.", title='J. B. Bachelder, The Story of the Battle of Gettysburg (1904 edition of the text to the Painting of the Repulse)',
                  note='Bachelder, writing of the group around Meade in the painting; the passage dates the start of the assault (about 15:00).'))
    ny = R.cite(SV('NY1', "bursting in the house and door-yard forced the general and his staff to seek temporary quarters with General Slocum on Powers' Hill", page='75'))
    mm = R.cite(LIB('MEADE-LL-v2', 'accordingly the general and his staff withdrew to the fenced yard in the immediate rear, where the work of directing the battle was resumed', title='George Meade, The Life and Letters of George Gordon Meade, vol. 2 (1913), Captain George Meade Jr.'))
    n4 = R.cite(NPSW('leister_place', 'As a result General Meade evacuated to a new headquarters.'))
    n5 = R.cite(NPSW('bldgs', 'Although the commanding general moved to a safer location, evidence of the bombardment is everywhere.'))
    hu = R.cite(OR(1, "was placed on the hill known as Slocum's headquarters, and near the Baltimore pike", rec='OR27-1-R028'))
    pa = R.cite(SV('PA2', 'more secure quarters in the woods, south of the Taneytown road', note='2nd Pennsylvania Cavalry narrative in Pennsylvania at Gettysburg (1914 edition, vol. 2); the sentence reads "another going through General Meades headquarters, and caus ing the general and staff to remove to more secure quarters in the woods, south of the Taneytown road" (OCR "Meades", "caus ing"); the quoted fragment is the contiguous part.'))
    R.sub('hq_moved_during_or_after_the_shelling', 'Meade\'s headquarters left the Leister house on 3 Jul because the shelling made it unsafe: "the general commanding" was at Slocum\'s headquarters when the signal officer was the last man at Meade\'s station (OR), and the shells "bursting in the house and door-yard forced the general and his staff to seek temporary quarters with General Slocum on Powers\' Hill" (NY at Gettysburg); NPS: "Meade evacuated to a new headquarters".', 'documented', [no, ny, n4, n5],
          why='Norton (OR), the Twelfth Corps narrative in NY at Gettysburg and the NPS pages agree on the move; Slocum\'s headquarters is the hill Hunt calls "the hill known as Slocum\'s headquarters" (Powers Hill).')
    R.sub('where_to_powers_hill_scenario', 'The staff only moved to the "fenced yard in the immediate rear" of the house, where "the work of directing the battle was resumed" (Captain Meade), and Meade was at Slocum\'s headquarters on Powers Hill when the assault began (about 15:00), reaching the field as it was repulsed (Bachelder).', 'documented', [mm, ba, hu],
          why='Two accounts for the same afternoon: during the cannonade the staff stood in the rear yard (the son), and by the start of the assault Meade was on Powers Hill (Bachelder, Norton). They are not contradictory in sequence but no source dates the move to a minute; carried as sequence (yard first, then Powers Hill) with the hour of the move open.')
    R.sub('second_destination_woods_south_of_the_taneytown_road', 'A regimental narrative of the 2nd Pennsylvania Cavalry says that a shell going through Meade\'s headquarters caused "the general and staff to remove to more secure quarters in the woods, south of the Taneytown road" (a different destination from Slocum\'s headquarters on Powers Hill).', 'documented', [pa],
          why='A retrospective regimental narrative (printed 1914) against Norton (OR) and the Twelfth Corps narrative (Powers Hill); the two destinations are not reconciled by any local text and both stay selectable (no default chosen here). The narrative names no hour.')
    R.sub('trigger_untenable', 'The trigger was that the house had become untenable.', 'documented', [ny, mm],
          why='NY1 "forced the general and his staff to seek temporary quarters"; Captain Meade: "so exposed that it was deemed best to avoid, if possible, the needless danger from flying splinters" (the OCR text before the quoted sentence).')
    R.sub('hour_of_the_move', 'The move took place at a given minute during the bombardment.', 'open_gap', [], support='none',
          why='The printed window is the whole of 3 Jul ("During the bombardment"); no local text gives a clock time.')
    R.lookup('OR27 pts 1-3: Slocum\'s headquarters, Powers Hill with Meade', 'OR27', 'Norton R017 p.206; Hunt R028 p.237', 'done')
    R.lookup('all local texts: Meade with Powers/Power\'s Hill, yard, staff, cannonade', 'ws9, state volumes', 'Bachelder 1904, Meade LL v2, NY1', 'done')
    R.unsupported('The clock time of the move and the identity of the "new headquarters" in the NPS text (the page does not name it).')
    return R.finish('corrected', 'open',
        'Meade\'s headquarters at the Leister house became untenable under the cannonade of 3 Jul: the staff withdrew to the fenced yard behind the house (Captain Meade), the shells forced the general and staff to seek quarters with Slocum on Powers Hill (NY at Gettysburg; Norton: "the general commanding, then at General Slocum\'s headquarters"), and Meade was on Powers Hill when the assault began, reaching the field as it was repulsed (Bachelder). One regimental narrative (2nd Pennsylvania Cavalry, PA vol. 2 p.806) names a different destination, "more secure quarters in the woods, south of the Taneytown road"; the two stay selectable. The hour of the move is not given.',
        register=['fence-3-EG-06'],
        product=['State schedule S-060: keep "Leister house -> Powers Hill (Slocum\'s headquarters)" with two documented steps (rear yard during the cannonade; Powers Hill by the start of the assault, about 15:00) and no clock time; do not move the headquarters at 13:00; carry "woods south of the Taneytown road" (2nd PA Cavalry, PA vol. 2 p.806) as a second selectable destination, no default.'],
        changes=['The row was a negative check; three sources (OR27-1 R017, NY1, Bachelder) now document the move and a fourth (Captain Meade) the intermediate step; the 2nd PA Cavalry narrative adds a second, different destination (woods south of the Taneytown road).'])


def S061():
    R = Row('S-061')
    h1 = R.cite(OR(1, 'when the enemy opened, at about 1 p. m., along his whole right, a furious cannonade on the left of our line', rec='OR27-1-R028', note='Hunt, Chief of Artillery.'))
    h2 = R.cite(OR(1, 'Our fire was well withheld until the first burst was over, excepting from the extreme right and left of our positions.', rec='OR27-1-R028'))
    h3 = R.cite(OR(1, 'I directed that the fire should be gradually stopped, which was done, and the enemy soon slackened his fire also', rec='OR27-1-R028', note='Sentence begins "About 2. 30 p. m. , finding our ammunition running low and that it was very unsafe to bring up loads of it".'))
    h4 = R.cite(OR(1, "About 3 p. m., and soon after the enemy's fire had ceased, he formed a column of attack", rec='OR27-1-R028'))
    ha = R.cite(OR(1, "About 1 o'clock, apparently by a given signal, the enemy opened upon our", rec='OR27-1-R076', note='Hancock, Second Corps; the sentence continues "front with the heaviest artillery fire I have ever known" (OCR "Iff ont with tiie").'))
    ha2 = R.cite(OR(1, 'After an hour and forty-five minutes, the fire of the enemy became less furious', rec='OR27-1-R076'))
    gi = R.cite(OR(1, 'for two hours the most terrific shower of shot and shell continued', rec='OR27-1-R098', note='Gibbon, 2nd Division, Second Corps; the sentence begins "o\'clock ... the enemy opened with his artillery all along his line".'))
    hz = R.cite(OR(1, 'The batteries did not at first reply, till the fire of the enemy becoming too terrible, they returned it till all their ammunition, excepting canister, had been expended', rec='OR27-1-R132', note='Hazard, Artillery Brigade, Second Corps; the sentence before says "for an hour and a quarter we were subjected to a very warm artillery fire".'))
    lee = R.cite(OR(2, 'About 1 p. m., at a given', rec='OR27-2-R426', note='Lee: "About 1 p. m., at a given signal, a heavy cannonade was opened, and continued for about two hours with marked effect upon the enemy."'))
    lee2 = R.cite(OR(2, 'continued for about two hours with marked effect', rec='OR27-2-R426'))
    pe = R.cite(OR(2, 'about 1 p. m., on the concerted', rec='OR27-2-R428', note='Pendleton: "about 1 p. m., on the concerted signal, our guns in position, nearly one hundred and fifty, opened fire along the entire line from right to left".'))
    es = R.cite(OR(2, 'you ordered me to give the signal for opening along the entire', rec='OR27-2-R466', note='Eshleman, Washington Artillery, to Colonel Alexander: "Between 1 and 2 p. m. you ordered me to give the signal for opening along the entire line. Two guns in quick succession were fired from Captain Miller\'s battery".'))
    es2 = R.cite(OR(2, 'Two gtms in quick succession were fired from Captain Miller\'s battery', rec='OR27-2-R466', note='OCR reads "gtms" for guns.'))
    es3 = R.cite(OR(2, 'Ahout thirty minutes after the signal guns had been fired, our infantry moved forward', rec='OR27-2-R466', note='OCR reads "Ahout" for About.'))
    de = R.cite(OR(1, 'signal of a gun fired to our left, a most terrific cannonade commenced', rec='OR27-1-R110', note='Devereux, 19th Massachusetts: "Everything remained quiet on our front until 1 p. m., when, at a signal of a gun fired to our left, a most terrific cannonade commenced on the batteries and the troops in the center of our line".'))
    lo = R.cite(OR(2, 'About 2 p. m. General Pickett', rec='OR27-2-R430', note='Longstreet: about 2 p.m. Pickett reported the troops in order; "Colonel Walton was ordered to open the batteries. The signal guns were fired, and all the batteries opened".'))
    hb = R.cite(LIB('NPS-HB9-1962', "At 1 p.m. two guns of Miller's Battery, posted near the Peach Orchard, opened fire in rapid succession.", title='NPS Historical Handbook 9, Gettysburg National Military Park (1962), "Artillery Duel at One O\'clock"'))
    hb3 = R.cite(LIB('NPS-HB9-1962', 'Union gunners on Cemetery Ridge waited a few minutes until the positions of the Confederate batteries were located', title='NPS Historical Handbook 9, Gettysburg National Military Park (1962), "Artillery Duel at One O\'clock"'))
    hb2 = R.cite(LIB('NPS-HB9-1962', 'For nearly 2 hours the duel continued, then the Union fire slackened.', title='NPS Historical Handbook 9, Gettysburg National Military Park (1962), "Artillery Duel at One O\'clock"'))
    ca = R.cite(LIB('NPS-COMMON-PRIDE-1', 'when all was ready I took my position & gave the signal & imnediately my Batteries all opened', title='NPS, K. R. Georg, "A Common Pride and Fame" part I (1981), quoting Col. E. P. Alexander', note='Alexander\'s own words as quoted by the NPS historian (OCR "imnediately"); the source letter itself is not in the local library.'))
    R.sub('start_about_13_00_by_signal', 'The cannonade opened at about 13:00 on 3 Jul on a concerted signal of two guns fired from Miller\'s battery of the Washington Artillery by order of Colonel Alexander (Eshleman: "between 1 and 2 p. m."), followed at once by the whole line of about 150 guns.', 'documented', [h1, lee, pe, ha, de, es, es2, hb],
          why='Union (Hunt, Hancock, Webb, Devereux) and Confederate reports (Lee, Pendleton) say about 1 p.m.; Longstreet says about 2 p.m. when Pickett reported ready and the signal guns were fired (a second value, not chosen between); Eshleman says between 1 and 2 p.m.')
    R.sub('trigger_alexander_signal', 'The trigger was Alexander\'s signal (the two guns).', 'documented', [es, es2, hb, ca],
          why='Eshleman: "you ordered me to give the signal"; Handbook 9 names the two guns of Miller\'s battery; Longstreet: "Colonel Walton was ordered to open the batteries. The signal guns were fired".')
    R.sub('union_reply_withheld_then_deliberate', 'The Union batteries withheld their fire at first and then replied deliberately: "Our fire was well withheld until the first burst was over", "The batteries did not at first reply"; Handbook 9: Union gunners "waited a few minutes".', 'documented', [h2, hz, hb3],
          why='This replaces the printed "Union slowdown about 13:30-14:00": the documented slowness is at the start (the first minutes), not at 13:30-14:00.')
    R.sub('hunt_orders_fire_stopped_14_30', 'Hunt ordered the Union fire "gradually stopped" at about 14:30 because ammunition was running low and the limbers were exploding, and the Confederate fire slackened soon after; Handbook 9 says the Union fire slackened after "nearly 2 hours" and Hunt had ordered a partial cessation.', 'documented', [h3, hb2],
          why='The printed "slow about 13:30-14:00" is not found: Hunt\'s order is at about 14:30 (in line with the r03 default for C-029). The printed trigger "Hunt orders" is supported.')
    R.sub('lull_14_45_to_15_00', 'The firing ended between 14:15 and 15:00: Hazard 1 h 15 min (to about 14:15), Hunt 14:30 then the enemy soon slackened, Hancock 1 h 45 min (to 14:45), Gibbon two hours and Lee about two hours (to about 15:00); about 15:00 the infantry column appeared (Hunt).', 'documented', [hz, h3, ha2, gi, lee2, h4],
          why='This is the range behind conflict C-029 (end 14:00, 14:30 or 15:00). Every value is a published primary statement; the printed lull "to about 14:45-15:00" is inside it. No default is chosen here.')
    R.sub('longstreet_2pm_alternative', 'Longstreet puts the order to open the batteries at about 14:00, after Pickett reported ready.', 'documented', [lo, es3],
          why='A second start value (14:00) against Lee, Pendleton and the Union reports (13:00); Eshleman: the infantry moved about thirty minutes after the signal guns, which fits 13:30-14:30 depending on the signal hour (C-030 step-off).')
    R.lookup('OR27 pts 1-2: the 3 Jul cannonade: start, signal, Union reply, end, in 14 reports', 'OR27', 'start 13:00 (Hunt, Hancock, Webb, Lee, Pendleton), 14:00 (Longstreet), "between 1 and 2" (Eshleman); end 14:15 to 15:00', 'done')
    R.lookup('NPS Handbook 9 (1954, 1962) and Common Pride part I: the artillery duel', 'NPS texts', 'two guns of Miller\'s battery at 1 p.m.; Union fire slackened after nearly two hours', 'done')
    R.unsupported('The PDF source Wiki-PC (Wikipedia, not admissible); the exact minute of the signal guns and of the Union "slowdown 13:30-14:00" (no text).')
    return R.finish('corrected', 'open',
        'The cannonade of 3 Jul began at about 13:00 on Alexander\'s signal (two guns of Miller\'s battery of the Washington Artillery, Eshleman: "between 1 and 2 p. m.") and the whole line of about 150 Confederate guns opened; the Union batteries withheld their fire for the first burst and then replied deliberately; Hunt ordered the Union fire gradually stopped at about 14:30 and the Confederate fire slackened soon after; the primary reports end the firing between 14:15 (Hazard) and 15:00 (Gibbon, Lee). The printed Union "slowdown about 13:30-14:00" is not found.',
        register=['fence-3-EG-07'],
        product=['State schedule S-061: start 13:00 with the signal guns (documented), Union fire withheld for the opening minutes and then deliberate, Hunt\'s order at 14:30 (documented), end between 14:15 and 15:00 with the C-029 scenarios (14:00, 14:30, 15:00 stay selectable; every one has a primary basis, 14:00 only as a Union-fire value). G-13 / G-14: the printed slowdown 13:30-14:00 has no source and should be dropped or marked inferred.'],
        changes=['The shard row printed no fence state and was a negative check; the cannonade sub-claims are now sourced.', 'Corrected: Union slowdown is at 14:30 by Hunt\'s order, not 13:30-14:00.'])


def S062():
    R = Row('S-062')
    pe1 = R.cite(OR(2, 'climb three high post and rail fences', rec='OR27-2-R441', note='Peyton, 19th Virginia (Garnett\'s brigade); the sentence continues "behind the last of which the enemy\'s skirmishers were first met and immediately driven in".'))
    pe2 = R.cite(OR(2, "behind the last of which the enemy's skirmishers were first met", rec='OR27-2-R441'))
    sh1 = R.cite(OR(2, 'a lane inclosed by two stout post and', rec='OR27-2-R552', note='OCR continues "jjlank fences" (post-and-plank fences). Shepard, 7th Tennessee (Archer\'s brigade), "Within ISO [180] or 200 yards of his works".'))
    sh2 = R.cite(OR(2, 'a very great obstruction', rec='OR27-2-R552', note='Sentence: "This was a very great obstruction to us, but the men rushed over as rapidly as they could".'))
    da1 = R.cite(OR(2, 'Not a gun was hred at us until we reached a strong post and rail fence', rec='OR27-2-R553', note='Davis (OCR "hred" for fired), Heth\'s division line: "about three-quarters of a mile from the enemy\'s position".'))
    da2 = R.cite(OR(2, 'interrupted by other fences of a similar character', rec='OR27-2-R553', note='Sentence: "Our advance across the fields was interrupted by other fences of a similar character, in crossing which the alignment became more or less deranged."'))
    ma = R.cite(LIB('NPS-CLI-PCB', 'where the parallel fences impeded the onward march, large numbers were shot down on account of the crowding at the openings where the fences had been thrown down, and on account of the halt in order to climb the fences', title="NPS Cultural Landscapes Inventory: Pickett's Charge Battlefield (2024), quoting Col. Rawley W. Martin (53rd Virginia) via Campbell 2004, pp. 67-68",
                    note='Second-hand: the NPS prints Martin\'s recollection with the citation (Campbell 2004: 67-68). Martin\'s own text is not in the local library.'))
    np1 = R.cite(LIB('NPS-CLR-ROT-V1', 'post and rail fences enclosing both sides of the road', title='NPS Cultural Landscape Report, Record of Treatment vol. I (2016)', note='Sentence: "Soldiers reaching Emmitsburg Road were exposed to more fire as they had to scale post and rail fences enclosing both sides of the road."'))
    np2 = R.cite(LIB('NPS-CLI-ERR', 'Although Union forces removed many of the north-south fences prior to the second day', title='NPS Cultural Landscapes Inventory: Emmitsburg Road Ridge Battlefield (2024)', note='Passage: "Although Union forces removed many of the north-south fences prior to the second day\'s battle, enough were standing on July 2-3 to hinder orderly troop movement."'))
    np3 = R.cite(LIB('NPS-CLI-ERR', 'Wooden post and rail fence along Emmitsburg Road, both sides of road, in front of Klingel Farm', title='NPS Cultural Landscapes Inventory: Emmitsburg Road Ridge Battlefield (2024)', note='Entry continues ": Portions dismantled for troop movement and breastwork construction; breastworks constructed on eastern side of road, north of Klingel".'))
    gi = R.cite(OR(1, 'tore down the fences and constructed breastworks', rec='OR27-1-R098', note='Gibbon: two regiments of Harrow\'s brigade "to occupy a position along that road and to the right of a brick house" on 2 Jul (about 16:00).'))
    ha = R.cite(OR(1, 'hastily taken down and piled in their front', rec='OR27-1-R099', note='Harrow: the 82nd New York and 15th Massachusetts on the Gettysburg and Emmitsburg road on 2 Jul, "partially protected by the rails of a fence which they had hastily taken down and piled in their front"; the OCR has a stray hyphen before "they".'))
    hn = R.cite(OR(1, 'a slight breastwork of such materials as the adjoining fences afforded', rec='OR27-1-R076'))
    jo = R.cite(OR(1, 'breastwork of rails behind the fence', rec='OR27-1-R101', note='Joslin, 15th Massachusetts, on the Emmitsburg road near a brick house on 2 Jul: "we built a small breastwork of rails behind the fence".'))
    me = R.cite(OR(1, 'leveling all the fences and stone walls', rec='OR27-1-R006', note='R006 is Meade\'s file; this passage is a letter attributed to the Third Corps side, not Meade\'s own words (fence-2 S-034, 2026-11-13).'))
    hu = R.cite(OR(1, 'removing such of the fences as were in the way', rec='OR27-1-R158', note='Humphreys, 2nd Division, Third Corps, morning of 2 Jul; no hour.'))
    hi = R.cite(OR(1, 'demolish all stone walls and fences in our front to the Emmitsburg road', rec='OR27-1-R146', note='Higgins, 86th New York, between 10:00 and 11:00 on 2 Jul: 35 men under Captain Baker.'))
    bo = R.cite(OR(1, 'clear away the fences in front of the division', rec='OR27-1-R167', note='Bodine, 26th Pennsylvania: "On the morning of July 2".'))
    wr = R.cite(OR(2, 'post and rail fences', rec='OR27-2-R539', nth=0, note='Wright (Anderson\'s division) crossed post-and-rail fences on 2 Jul; another sector. First of the occurrences on p.623.'))
    be = R.cite(OR(1, 'At 3 o\'clock the enemy\'s line of battle left the woods in our front; moved in perfect order across the Emmitsburg road', rec='OR27-1-R104', note='Webb, about 15:00 on 3 Jul.'))
    es3 = R.cite(OR(2, 'Ahout thirty minutes after the signal guns had been fired, our infantry moved forward', rec='OR27-2-R466', note='OCR reads "Ahout" for About.'))
    R.sub('fences_on_both_sides_of_road_standing_on_3_jul', 'Post-and-rail (and post-and-plank) fences stood on the line of the advance on 3 Jul and had to be climbed: Peyton climbed "three high post and rail fences"; Shepard reached "a lane inclosed by two stout post and plank fences" 180-200 yards from the Union works, "a very great obstruction"; Davis met "a strong post and rail fence" and "other fences of a similar character".', 'documented', [pe1, pe2, sh1, sh2, da1, da2],
          why='Three Confederate brigade or regiment reports. The "lane inclosed by two fences" is the double fence along a road; Shepard does not name the road; NPS names the Emmitsburg Road (below).')
    R.sub('double_fences_both_sides_of_the_emmitsburg_road', 'Double post-and-rail fences enclosed both sides of the Emmitsburg Road, and the soldiers who reached it had to scale them.', 'documented', [np1, np3, sh1, ma],
          why='NPS Record of Treatment vol. I and the Emmitsburg Road Ridge inventory (institutional secondary, Law cl.4: not a primary but a non-lead source), supported by Shepard\'s "lane inclosed by two fences" and Martin\'s "parallel fences" (via NPS).')
    R.sub('slowing_and_climbing_at_the_road', 'The fences slowed the advance and the attackers broke ranks to climb: "large numbers were shot down on account of the crowding at the openings where the fences had been thrown down, and on account of the halt in order to climb the fences" (Martin, 53rd Virginia); Davis: the alignment "became more or less deranged".', 'documented', [ma, da2, pe1],
          why='Printed "slowed the charge about 15:30-16:15; attackers broke ranks to climb": supported without the hours. The clock: Webb has the line leaving the woods and crossing the road about 15:00 and Eshleman about 30 minutes after the signal; no text gives 15:30-16:15 for the fences.')
    R.sub('intact_morning_of_3_jul', 'The Emmitsburg Road fences were "Intact" on the morning of 3 Jul.', 'documented', [gi, ha, hn, jo, hi, bo, hu, me, np2, np3], support='partial',
          why='Contradicted in part by Jul 2 removals: Higgins\' 35 men "to demolish all stone walls and fences in our front to the Emmitsburg road" (10:00-11:00), Bodine\'s regiment "to clear away the fences" (morning), Humphreys "removing such of the fences as were in the way", Gibbon\'s and Harrow\'s regiments and Joslin\'s using fences as breastworks along the road near a brick house; NPS: "Union forces removed many of the north-south fences prior to the second day\'s battle, enough were standing on July 2-3 to hinder orderly troop movement" and the east-side breastwork north of the Klingel farm. Existence on 3 Jul is documented; "intact" is not (RULE-03 holds: the removals are after 00:00 on 2 Jul).')
    R.sub('fences_in_anderson_sector_2_jul', 'Anderson\'s division also crossed post-and-rail fences on 2 Jul (another sector).', 'documented', [wr], why='Wright R539 p.623.')
    R.sub('heavily_hit_by_bullets_and_artillery_836_holes', 'The fences were heavily hit by bullets and artillery on 2-3 Jul; "one 16-ft rail had 836 holes; a Confederate described perforated slabs".', 'open_gap', [], support='none',
          why='Searched 836, perforated, riddled in all local texts: no fence statement. The source is Savas-Hessler (not local, and the publisher excerpt was too large to fetch in 2026-11-04; not retried).')
    R.sub('breach_points_not_documented', 'Exact breach points are not documented.', 'inferred', [ma], support='partial',
          why='The PDF itself says so. Martin and Davis speak of "openings where the fences had been thrown down" and fences "interrupted"; no position is given.')
    R.lookup('OR27 pts 1-3: fences on the line of advance on 3 Jul (Peyton, Shepard, Davis, Wright) and the removals on 2 Jul (nine reports)', 'OR27', 'all quotes above; the shard\'s eleven quotations re-matched exactly', 'done')
    R.lookup('NPS texts (CLI Pickett\'s Charge, CLI Emmitsburg Road Ridge, CLR record of treatment, Common Pride): Emmitsburg Road fences', 'NPS texts', 'both sides, scaled, thrown down openings; none gives a count of holes', 'done')
    R.lookup('all local texts: 836 with holes/perforated', 'all', 'no hit', 'failed')
    R.unsupported('The 836-hole rail and "a Confederate described perforated slabs" (Savas-Hessler excerpt, not local).')
    R.unsupported('Fence state at breach points; the clock hours 15:30-16:15 for the fences.')
    return R.finish('corrected', 'blocked_host',
        'Emmitsburg Road fences: double post-and-rail (post-and-plank) fences enclosed both sides of the road and stood on the line of the advance on 3 Jul (Peyton, Shepard, Davis; NPS); the attackers had to climb them and crowded at the openings where they had been thrown down (Martin via NPS; Davis). They were not intact along the whole road: on 2 Jul Union troops took down or levelled fences to the road and built rail breastworks along it (Higgins, Bodine, Humphreys, Gibbon, Harrow, Hancock, Joslin; NPS). The 836-hole rail and the 15:30-16:15 hours for the fences are not supported.',
        register=['fence-3-EG-08'],
        blocked_host=[{'url': 'https://www.savasbeatie.com/content/Titles/Fall%202014/Pickett%20Hessler/excerpt%20From%20Picketts%20Charge.pdf', 'what_to_read': 'The publisher\'s excerpt of Hessler, Pickett\'s Charge at Gettysburg (Savas Beatie, 2009/2014; key Savas-Hessler): the passage that says one 16-foot rail had 836 holes and quotes the Confederate who described perforated slabs. The earlier fetch stopped at the 10 MB limit; it is a large PDF (not retried here; the host is not on the reachable list).'},
                      {'url': 'Gettysburg Daily, "fences along the Emmitsburg Road" (key GD-EmmRd) and American Battlefield Trust, "Pickett\'s Charge 3:45-4:15" (key ABT-Charge)', 'what_to_read': 'The plan prints only the key and title. The statements "double post-and-rail fences both sides of the road", "intact morning Jul 3" and the 15:30-16:15 slowing window. Lead sources; the primary side is above.'}],
        product=['FEN-emmitsburg-road: split by sector and date: (a) segments pulled down or levelled on 2 Jul (Higgins 10:00-11:00 Third Corps front, Bodine, Humphreys, the Harrow/Gibbon/Joslin position near the brick house) and the east-side breastwork north of Klingel, (b) segments standing on 3 Jul (Peyton, Shepard, Davis, NPS) with double fences on both sides; "Intact morning Jul 3" must not be drawn for the whole road. RULE-03 is respected (all removals after 00:00 on 2 Jul). P-10: the pre-existing fences keep no construction animation. Slowing at the road: after about 15:00 (Webb), not stated more closely. 836 holes: drop or mark open gap.'],
        changes=['The eleven quotations of the 2026-11-04 row are re-matched exactly (offsets in the citations).', 'Added Davis (R553 p.651) and Shepard\'s "lane inclosed by two ... fences", Martin via NPS and the NPS Record of Treatment for the double fences.', '"Intact morning Jul 3" is partially contradicted (Jul 2 removals) and the 836 holes stay unsupported.'])
